"""Long data -> one value per athlete per window -> STEN against position norms."""
from __future__ import annotations

import importlib.util
from datetime import date

import pandas as pd

import config
from src.load import load
from src.sten import ladder_from_samples, sten

LBS_PER_KG = 2.20462


def _vald_norms():
    spec = importlib.util.spec_from_file_location("vald_norms", config.VALD_NORMS_PY)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def _window_bounds(w: dict, year: int) -> tuple[pd.Timestamp, pd.Timestamp]:
    return pd.Timestamp(f"{year}-{w['start']}"), pd.Timestamp(f"{year}-{w['end']}")


def current_cycle(windows: list[dict], asof: date) -> list[dict]:
    """Latest occurrence of each window that has started by the as-of date."""
    out = []
    for w in windows:
        year = asof.year
        if _window_bounds(w, year)[0] > pd.Timestamp(asof):
            year -= 1
        start, end = _window_bounds(w, year)
        out.append({**w, "year": year, "from": start, "to": min(end, pd.Timestamp(asof))})
    return sorted(out, key=lambda w: w["from"])


def _tag_windows(df: pd.DataFrame, windows: list[dict]) -> pd.DataFrame:
    df = df.copy()
    df["year"] = df["date"].dt.year
    df["wkey"] = None
    for w in windows:
        md = df["date"].dt.strftime("%m-%d")
        df.loc[(md >= w["start"]) & (md <= w["end"]), "wkey"] = w["key"]
    return df.dropna(subset=["wkey"])


def _perch_relative(perch: pd.DataFrame, bw: pd.DataFrame) -> pd.DataFrame:
    # shortcut: body weight is the nearest ForceDecks weigh-in within a year of the lift;
    # upgrade to the Football body-weight log if ForceDecks weigh-ins get sparse.
    bw = bw.sort_values("date").rename(columns={"value": "bw_kg"})
    perch = perch.sort_values("date")
    m = pd.merge_asof(perch, bw, on="date", by="name_key", direction="nearest",
                      tolerance=pd.Timedelta(days=365))
    m["value"] = m["value"] / (m["bw_kg"] * LBS_PER_KG)
    return m.dropna(subset=["value"]).drop(columns="bw_kg")


def build(asof: date) -> dict:
    cfg = config.settings()
    long, pos, bw, fresh = load(cfg)
    metrics = cfg["metrics"]
    field_to_key = {(m["source"], m["field"]): m["key"] for m in metrics}

    is_perch = long["source"] == "perch"
    long = pd.concat([long[~is_perch], _perch_relative(long[is_perch], bw)])
    long["metric"] = [field_to_key.get(k) for k in zip(long["source"], long["field"])]
    long = _tag_windows(long.dropna(subset=["metric"]), cfg["windows"])

    agg = {m["key"]: m["agg"] for m in metrics}
    g = long.groupby(["name_key", "year", "wkey", "metric"])["value"]
    aw = g.agg(["mean", "max", "count"]).reset_index()
    aw["value"] = [r["max"] if agg[r.metric] == "max" else r["mean"] for _, r in aw.iterrows()]
    aw["group"] = aw["name_key"].map(pos)

    # Norm ladders: [metric][group] -> P5..P95
    vald = _vald_norms()
    ladders, directions = {}, {}
    pool = aw[(aw["year"] >= cfg["norm_start_year"]) & aw["group"].notna()]
    for m in metrics:
        ladders[m["key"]] = {}
        if m["norm"] == "vald":
            row = vald.ROWS.index(m["vald_row"])
            directions[m["key"]] = vald.DIRECTION[vald.MAP[m["vald_row"]][0]]
            for grp, levels in vald.DATA.items():
                ladders[m["key"]][grp] = levels[cfg["vald_level"]][row]
        else:
            directions[m["key"]] = 1
            for grp, sub in pool[pool["metric"] == m["key"]].groupby("group"):
                ladders[m["key"]][grp] = ladder_from_samples(sub["value"], cfg["norm_min_n"])

    cycle = current_cycle(cfg["windows"], asof)
    cur = pd.concat([
        aw[(aw["year"] == w["year"]) & (aw["wkey"] == w["key"])] for w in cycle
    ])
    cur = cur[cur["group"].notna()]  # football athletes with a mapped position only

    names = (long[long["source"] != "perch"].groupby("name_key")["name"]
             .agg(lambda s: s.mode().iat[0]).to_dict())

    athletes = []
    for key, sub in cur.groupby("name_key"):
        grp = pos[key]
        vals: dict = {}
        for _, r in sub.iterrows():
            lad = ladders[r.metric].get(grp)
            vals.setdefault(r.wkey, {})[r.metric] = {
                "v": round(float(r.value), 2),
                "s": sten(float(r.value), lad, directions[r.metric]),
                "n": int(r["count"]),
            }
        athletes.append({"name": names.get(key, key.title()), "group": grp, "values": vals})
    athletes.sort(key=lambda a: (a["group"], a["name"]))

    return {
        "asof": asof.isoformat(),
        "fresh": fresh,
        "vald_level": cfg["vald_level"],
        "norm_start_year": cfg["norm_start_year"],
        "windows": [{"key": w["key"], "label": f"{w['label']} {w['year']}",
                     "from": w["from"].strftime("%Y-%m-%d"), "to": w["to"].strftime("%Y-%m-%d")}
                    for w in cycle],
        "metrics": [{k: m[k] for k in ("key", "label", "unit", "norm", "agg")} for m in metrics],
        "ladders": ladders,
        "athletes": athletes,
    }

