with duckdb.connect(str(config.FORCEPLATE_DB), read_only=True) as c:
    V = {name_key(n) for (n,) in c.sql("select distinct athlete_name from raw_tests where test_date>='2026-08-01' and (sport is null or sport='Football') and position <> ''").fetchall()}
    Vall = {name_key(n) for (n,) in c.sql("select distinct athlete_name from raw_tests where test_date>='2026-06-01'").fetchall()}
with duckdb.connect(str(config.GPS_DB), read_only=True) as c:
    G = {name_key(n) for (n,) in c.sql("select distinct a.name from athlete_sessions s join athletes a on a.catapult_id=s.athlete_id where s.session_date>='2026-08-01'").fetchall()}
with duckdb.connect(str(config.PERCH_DB), read_only=True) as c:
    P = {name_key(n) for (n,) in c.sql("select distinct name_normalized from perch_1rm where test_date>='2026-08-01'").fetchall()}
print(f"roster {len(R)} | VALD fb {len(V)} | GPS {len(G)} | Perch {len(P)}")
for lab,S in (("VALD",V),("GPS",G),("Perch",P)):
    print(f"{lab}: on roster {len(S & R.keys())}, not on roster {len(S - R.keys())}")
print("roster with no VALD", len(R.keys()-Vall), "| no GPS", len(R.keys()-G), "| no Perch", len(R.keys()-P))
def near(n, pool):
    f,l = n.split()[0], n.split()[-1]
    return [k for k in pool if k.split()[-1]==l or (k.split()[0]==f and k.split()[-1][:3]==l[:3])]
print("\n-- not on roster -> near roster names")
for lab,S in (("VALD",V),("GPS",G),("Perch",P)):
    for n in sorted(S - R.keys()): print(f"  {lab:5s} {n!r:32s} -> {near(n, R.keys())}")
print("\n-- roster names absent everywhere since Aug:", sorted(R.keys() - V - G - P))
