"""Quick diagnostic — test /stats endpoint with various slug combinations.

Run from gps_report/:
    python test_stats.py

Prints the raw JSON response (or error) for each attempt so you can see
exactly what field names come back and which slugs work.
"""

import json
import os
import sys

import requests
from dotenv import load_dotenv

load_dotenv()

TOKEN = os.environ.get("CATAPULT_TOKEN", "").strip()
if not TOKEN:
    sys.exit("ERROR: CATAPULT_TOKEN not set in .env")

BASE_URL = "https://connect-us.catapultsports.com/api/v6"
ACTIVITY_ID = "e6778cb6-69a1-44ff-989c-09faffa9d3bd"

HEADERS = {
    "Authorization": f"Bearer {TOKEN}",
    "Content-Type": "application/json",
    "Accept": "application/json",
}


def post_stats(label: str, body: dict) -> None:
    print(f"\n{'='*60}")
    print(f"TEST: {label}")
    print(f"Body: {json.dumps(body, indent=2)}")
    print("-" * 60)
    try:
        resp = requests.post(f"{BASE_URL}/stats", headers=HEADERS, json=body, timeout=60)
        print(f"Status: {resp.status_code}")
        ],
        "parameters": ["max_velocity", "total_distance"],
        "group_by": ["athlete"],
        "source": "cached_stats",
    },
)

# ── Test 3: Minimal — just total_distance, no velocity ───────────────────────
post_stats(
    "Minimal — only total_distance + average_player_load",
    {
        "filters": [
            {"name": "activity_id", "comparison": "=", "values": [ACTIVITY_ID]}
        ],
        "parameters": ["average_player_load", "total_distance"],
        "group_by": ["athlete"],
        "source": "cached_stats",
    },
)

# ── Test 4: No parameters filter (return all) ────────────────────────────────
post_stats(
    "No parameters specified — return everything",
    {
        "filters": [
            {"name": "activity_id", "comparison": "=", "values": [ACTIVITY_ID]}
        ],
        "group_by": ["athlete"],
        "source": "cached_stats",
    },
)

# ── Test 5: annotation_stats source instead of cached_stats ──────────────────
post_stats(
    "annotation_stats source (instead of cached_stats)",
    {
        "filters": [
            {"name": "activity_id", "comparison": "=", "values": [ACTIVITY_ID]}
        ],
        "parameters": ["average_player_load", "total_distance"],
        "group_by": ["athlete"],
        "source": "annotation_stats",
    },
)

print("\n" + "=" * 60)
print("Done. Check which tests returned rows and note the field names.")

