from dotenv import load_dotenv
load_dotenv()
T = os.environ["CATAPULT_TOKEN"].strip()
H = {"Authorization": f"Bearer {T}", "Content-Type": "application/json", "Accept": "application/json"}
body = {"filters": [{"name": "activity_id", "comparison": "=", "values": ["ce635ea4-7ac7-4264-8ae7-ab92ddc98ca8"]}],
        "parameters": ["total_player_load","average_player_load","average_player_load_session","player_load_per_minute","total_duration","field_time"],
        "group_by": ["athlete"], "source": "cached_stats"}
r = requests.post("https://connect-us.catapultsports.com/api/v6/stats", headers=H, json=body, timeout=60)
print("status", r.status_code)
rows = r.json() if isinstance(r.json(), list) else r.json().get("data", [])
print("athletes", len(rows), "| keys:", sorted(k for k in rows[0] if "load" in k or "duration" in k or "time" in k) if rows else None)
def f(x, k):
    try: return float(x.get(k))
    except: return None
ratios, ratios_ft, avg_ratio = [], [], []
for x in rows:
    tpl, plpm, dur, ft, apl = f(x,"total_player_load"), f(x,"player_load_per_minute"), f(x,"total_duration"), f(x,"field_time"), f(x,"average_player_load")
